// Generated by `just generate` from `src/plugins/claudetto/slices/setup/adapters/hook-exclude.ts`. Edit the source and run `just generate`.
// The exclude step as one function over a port, so that the CLI (`exclude-step.ts`) and the `session.start` hook (`mod.ts`) share it.
// This file is in the import graph of the hooks module, so it has no `node:` import and no use of `Bun`.
// A folder that is not in a git repository gets no change.

import {
  excludeLines,
  RUNTIME_PATTERNS,
  samplePath,
} from "../domain/exclude.ts";

/** What the exclude step needs from its host. */
export type ExcludePort = {
  /** The exit code and trimmed stdout of `git args`, or `undefined` when git does not run. */
  git: (args: string[]) => Promise<{ code: number; out: string } | undefined>;
  /** The text of the file `file`, or `""` when it is missing. A path is absolute or relative to the working folder. */
  read: (file: string) => Promise<string>;
  /** Write `text` to `file`, and make its folders. */
  write: (file: string, text: string) => Promise<void>;
};

/**
 * The lines that this step added to `.git/info/exclude` of the repository of the working folder, or `[]`.
 * A second call adds nothing, because `excludeLines` skips each present pattern.
 */
export const addExcludes = async ({
  git,
  read,
  write,
}: ExcludePort): Promise<string[]> => {
  const found = await git(["rev-parse", "--git-path", "info/exclude"]);
  if (found?.code !== 0 || !found.out) return [];
  const ignored: string[] = [];
  for (const pattern of RUNTIME_PATTERNS)
    if ((await git(["check-ignore", "-q", samplePath(pattern)]))?.code === 0)
      ignored.push(pattern);
  const text = await read(found.out);
  const lines = excludeLines(text, ignored);
  if (lines.length === 0) return [];
  const lead = text === "" || text.endsWith("\n") ? "" : "\n";
  await write(found.out, `${text}${lead}${lines.join("\n")}\n`);
  return lines;
};
